CREATE TABLE IF NOT EXISTS platform_final_readiness_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gate_key text NOT NULL UNIQUE, decision text NOT NULL DEFAULT 'NO_GO', checks jsonb NOT NULL DEFAULT '[]'::jsonb, green_count integer NOT NULL DEFAULT 0, amber_count integer NOT NULL DEFAULT 0, red_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz)